import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search inventory products by name (case-insensitive).',
      inputSchema: {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description: 'Search string matched against product names (case-insensitive).'
          },
          limit: {
            type: 'integer',
            minimum: 1,
            maximum: 10,
            description: 'Maximum number of results to return (1 to 10). Defaults to 10.'
          }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (typeof args.query !== 'string') {
    throw new Error('Invalid arguments: "query" is required and must be a string.');
  }

  let limit = args.limit;
  if (limit === undefined || limit === null) {
    limit = 10;
  } else if (!Number.isInteger(limit) || limit < 1 || limit > 10) {
    throw new Error('Invalid arguments: "limit" must be an integer between 1 and 10.');
  }

  const needle = args.query.toLowerCase();
  const matches = products
    .filter((p) => typeof p.name === 'string' && p.name.toLowerCase().includes(needle))
    .slice(0, limit);

  const text = matches.map((p) => `${p.id}\t${p.name}`).join('\n');

  return {
    content: [
      {
        type: 'text',
        text
      }
    ]
  };
}

